  sourceDigest: draft.sourceDigest,
  glossaryBinding: prep.glossaryBinding,
  selectionDigest: sha256(stableJson(selection)),
  edits: draft.edits,
  candidateDigest: sha256(candidate),
};
writeFileSync(`${S}editing.json`, JSON.stringify(editing, null, 2));
